def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid divider row or column.
    divider_row = next(
        (r for r in range(h) if grid[r][0] != 0 and len(set(grid[r])) == 1),
        None
    )
    if divider_row is not None:
        first = grid[:divider_row]
        second = grid[divider_row + 1:]
        return [
            [2 if a != 0 and b != 0 else 0 for a, b in zip(row_a, row_b)]
            for row_a, row_b in zip(first, second)
        ]

    divider_col = next(
        c for c in range(w)
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))
    )
    return [
        [2 if grid[r][c] != 0 and grid[r][c + divider_col + 1] != 0 else 0
         for c in range(divider_col)]
        for r in range(h)
    ]
